-- The two checklists published on 2026-10-15: telling a child something
-- hard (Parenting) and the night before a procedure (Health).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-15`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('telling-your-child-something-hard', 'Telling Your Child Something Hard', 'For the news you have to give a child — a separation, a death, a move, a diagnosis in the family — and the hour before you say it. It helps you decide what to tell them, keep it in their language, and leave room for whatever comes back.', 'Parenting', '["Decide the one sentence they need first — children hear the first line and little else.", "Pick a time that is not bedtime or a school morning — they need somewhere to put it afterward.", "Say it in words they already use — a softened version gets misunderstood.", "Tell them plainly that it is not their fault — children assume they caused things.", "Say what will stay the same for them — the practical questions are their real worry.", "Let the silence sit without filling it — processing often looks like nothing happening.", "Answer the question asked, not the whole thing — they will come back for more in their own time.", "Tell their teacher or another adult tomorrow — a child does the rest of their day elsewhere."]'::jsonb, 'as needed', array['Parenting', 'Communication']::text[], 1, '2026-10-15T16:00:00+00:00'::timestamptz),
  ('the-night-before-a-procedure', 'The Night Before a Procedure', 'For the evening before an operation or a procedure, when the instructions are long and the mind is loud. It helps you get the practical things done early, set up the day after, and give the fear somewhere to go before lights out.', 'Health', '["Read the instructions again and write the times — fasting and medication rules are easy to misremember.", "Pack the bag tonight, not in the morning — morning you will be hungrier and less patient.", "Confirm who is taking you and collecting you — most procedures will not discharge you alone.", "Put food and easy meals in for afterward — the day after is not a shopping day.", "Write your questions on your phone now — you will be asked if you have any, and go blank.", "Tell one person what time it starts — being thought about at the hour helps.", "Say the frightening thought out loud once — unsaid fear keeps you awake longer.", "Put something undemanding on until you sleep — a bad night is normal, not a problem to solve."]'::jsonb, 'as needed', array['Anxiety', 'Body']::text[], 1, '2026-10-15T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
